package main

import (
	"flag"
	"fmt"
	"net/http"
	"os"
	"strings"

	mcptools "github.com/mvanhorn/printing-press-library/library/media-and-entertainment/drivethrurpg/internal/mcp"
	"github.com/mark3labs/mcp-go/server"
)

func main() {
	transport := flag.String("transport", envDefault("DRIVETHRURPG_MCP_TRANSPORT", "stdio"), "MCP transport: stdio or http")
	listen := flag.String("listen", envDefault("DRIVETHRURPG_MCP_LISTEN", "127.0.0.1:8080"), "Listen address for --transport http")
	endpoint := flag.String("endpoint", envDefault("DRIVETHRURPG_MCP_ENDPOINT", "/mcp"), "HTTP endpoint path for --transport http")
	flag.Parse()

	s := server.NewMCPServer(
		"DriveThruRPG",
		"1.0.0",
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	var err error
	switch strings.ToLower(strings.TrimSpace(*transport)) {
	case "", "stdio":
		err = server.ServeStdio(s)
	case "http", "streamable-http", "streamable_http":
		httpServer := server.NewStreamableHTTPServer(s, server.WithEndpointPath(*endpoint))
		fmt.Fprintf(os.Stderr, "DriveThruRPG MCP HTTP server listening on http://%s%s\n", *listen, normalizedEndpoint(*endpoint))
		err = httpServer.Start(*listen)
		if err == http.ErrServerClosed {
			err = nil
		}
	default:
		err = fmt.Errorf("unsupported MCP transport %q (use stdio or http)", *transport)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
		os.Exit(1)
	}
}

func envDefault(name, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(name)); value != "" {
		return value
	}
	return fallback
}

func normalizedEndpoint(endpoint string) string {
	endpoint = "/" + strings.Trim(endpoint, "/")
	if endpoint == "/" {
		return "/mcp"
	}
	return endpoint
}
